const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws);

const order = data.find(r => r['Order ID'] === 'ORD-6C71B1');
if (order) {
  order['Status'] = 'confirmed';
  const newWs = XLSX.utils.json_to_sheet(data);
  wb.Sheets['Orders'] = newWs;
  XLSX.writeFile(wb, 'testbed/data/order_summary.xlsx');
  console.log('Updated ORD-6C71B1 status to confirmed');
} else {
  console.log('Order not found');
}
"

